<template> <SwitchRoot :checked="modelValue" class="relative inline-flex h-6 w-10 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 dark:focus:ring-offset-gray-800 focus:ring-ring dark:focus:ring-ring" :class="modelValue ? 'dark:bg-primary bg-primary' : 'bg-muted dark:bg-muted'" @update:checked="updateChecked" > <SwitchThumb class="inline-block transform rounded-full bg-background dark:bg-background transition-transform" :class="modelValue ? 'translate-x-5 w-4 h-4' : 'translate-x-1.5 w-3 h-3'" /> </SwitchRoot> </template> <script setup> import { SwitchRoot, SwitchThumb } from 'radix-vue'; defineProps({ modelValue: { type: Boolean, required: true } }); const emit = defineEmits(['update:modelValue']); const updateChecked = (checked) => { emit('update:modelValue', checked); }; </script>